# -*- coding: utf-8 -*-
"""Arquitetura de sistemas (ARQ) — cota 42."""
from comum import Q

E = "ARQ"
QUESTOES = [
    # ---------------- variações ----------------
    Q(E, "06", 11, sub="11.7", pai="ESP-ARQ-0001", top="Microsserviços: Saga", k="arq-saga-orq",
      enun="Em uma cooperativa de crédito, a contratação de um consórcio envolve os microsserviços Propostas, Cobrança e Notificações, cada um com seu próprio banco de dados. Um componente central recebe o pedido, manda cada serviço executar sua transação local na ordem definida e, se a Cobrança falhar, comanda as transações de compensação nos serviços que já concluíram suas etapas. Essa solução corresponde a uma",
      alts=["saga orquestrada.",
            "saga coreografada.",
            "transação distribuída com commit em duas fases (2PC).",
            "implementação do padrão CQRS com Event Sourcing.",
            "aplicação do padrão Bulkhead com fallback."],
      gab="A",
      com="**Gabarito: A.** Na saga **orquestrada** um orquestrador central diz a cada serviço o que fazer e dispara as compensações em caso de falha.\n\n(B) Na saga coreografada não há coordenador: cada serviço publica eventos e reage aos eventos dos outros. (C) O 2PC é um protocolo bloqueante com coordenador de transação global, justamente o que a saga evita; não usa compensações. (D) CQRS separa os modelos de leitura e escrita e Event Sourcing guarda a sequência de eventos; nenhum dos dois coordena a transação de negócio. (E) Bulkhead isola recursos por dependência e fallback dá resposta alternativa; não tratam consistência entre serviços."),

    Q(E, "06", 9, sub="9.7", pai="ESP-ARQ-0002", top="Padrões de projeto GoF, MVC e arquitetura em camadas", k="arq-mvc-model",
      enun="Considere uma aplicação web de consulta de investimentos construída segundo o padrão MVC. O componente que concentra os dados e as regras de negócio (por exemplo, o cálculo da rentabilidade líquida de um CDB) e que, no MVC clássico, notifica as visões quando seu estado muda é o",
      alts=["Controller.",
            "View.",
            "Model.",
            "Front Controller.",
            "Presenter."],
      gab="C",
      com="**Gabarito: C.** O **Model** guarda os dados, as regras de negócio e o estado; no MVC clássico notifica as views (padrão Observer).\n\n(A) O Controller recebe as entradas do usuário, aciona o modelo e escolhe a view. (B) A View apenas apresenta os dados. (D) Front Controller é um ponto único que recebe todas as requisições e as despacha (ex.: DispatcherServlet); não contém regra de negócio. (E) Presenter é o mediador do padrão MVP, não um componente do MVC."),

    Q(E, "06", 9, sub="9.7", pai="ESP-ARQ-0002", top="Padrões de projeto GoF, MVC e arquitetura em camadas", k="arq-mvvm",
      enun="Em um aplicativo cuja interface se liga, por *data binding*, a um componente que expõe propriedades e comandos, sem que a tela precise conhecer o modelo de domínio nem ser atualizada manualmente pelo código, adota-se o padrão",
      alts=["MVC clássico, com a View observando diretamente o Model.",
            "MVP, com a View passiva atualizada pelo Presenter.",
            "Front Controller, com despacho centralizado de requisições.",
            "MVVM, com a View ligada à ViewModel por data binding.",
            "Arquitetura em camadas fechada, com a apresentação acessando só o negócio."],
      gab="D",
      com="**Gabarito: D.** No **MVVM** a ViewModel expõe dados e comandos aos quais a View se liga por **data binding** (WPF, Angular, Vue).\n\n(A) No MVC clássico a View consulta o Model e é notificada por Observer; não há ViewModel. (B) No MVP a View é passiva e o Presenter a atualiza explicitamente, sem data binding. (C) Front Controller trata do recebimento de requisições, não da ligação de dados com a tela. (E) Camadas fechadas descrevem dependências entre camadas, não o mecanismo de atualização da interface."),

    Q(E, "06", 9, sub="9.8", pai="ESP-ARQ-0003", top="Padrões de projeto GoF, MVC e arquitetura em camadas", k="arq-camadas-tiers",
      enun="Sobre arquiteturas em camadas, é correto afirmar:",
      alts=["Em camadas abertas (relaxadas), cada camada só pode acessar a camada imediatamente inferior, o que maximiza o isolamento.",
            "Uma aplicação organizada em três camadas lógicas (layers) obrigatoriamente é implantada em três máquinas distintas (tiers).",
            "Na arquitetura cliente-servidor em duas camadas físicas, o cliente costuma conter a interface e boa parte da lógica, acessando diretamente o servidor de banco de dados.",
            "O antipadrão sinkhole ocorre quando a camada de apresentação acessa diretamente o banco de dados, sem passar pelo negócio.",
            "Trocar o SGBD exige alterar todas as camadas, pois a camada de dados não isola a persistência."],
      gab="C",
      com="**Gabarito: C.** No modelo **2 tier** (cliente gordo + SGBD), a aplicação cliente reúne interface e lógica e fala direto com o servidor de banco.\n\n(A) Descreve as camadas **fechadas** (estritas); nas abertas uma camada pode acessar qualquer inferior. (B) Layer é divisão lógica e tier é física: três layers podem rodar em um único tier. (D) Sinkhole é a camada que apenas repassa chamadas sem acrescentar lógica; acesso direto da apresentação ao banco é violação de camadas fechadas. (E) Isolar a persistência na camada de dados é justamente o que permite trocar o banco sem mexer nas outras camadas."),

    Q(E, "06", 11, sub="11.6", pai="ESP-ARQ-0004", top="Microsserviços", k="arq-bff",
      enun="Um banco mantém um aplicativo móvel, um internet banking web e uma API para parceiros. Cada canal precisa de respostas com formatos e agregações diferentes, e a equipe decide criar um gateway específico para cada tipo de cliente, moldado às necessidades de cada front-end. Esse padrão é denominado",
      alts=["Service Mesh.",
            "Backend for Frontend (BFF).",
            "Enterprise Service Bus (ESB).",
            "Sidecar.",
            "Strangler Fig."],
      gab="B",
      com="**Gabarito: B.** O **BFF** é uma variação do API Gateway com um gateway por tipo de cliente (mobile, web, parceiros).\n\n(A) Service mesh cuida da comunicação **interna** serviço a serviço (mTLS, retries, observabilidade). (C) O ESB é o barramento de integração centralizado típico da SOA, não um gateway por canal. (D) Sidecar é um contêiner auxiliar implantado junto a cada serviço. (E) Strangler Fig é padrão de migração gradual de legado."),

    Q(E, "06", 11, sub="11.6", pai="ESP-ARQ-0004", top="Microsserviços", k="arq-gateway-incorreta",
      enun="Considere as atribuições a seguir em uma arquitetura de microsserviços. NÃO é função recomendada para um API Gateway:",
      alts=["rotear cada requisição externa ao serviço responsável.",
            "validar tokens OAuth 2.0 de forma centralizada antes de repassar as chamadas.",
            "aplicar limitação de taxa (rate limiting) e cotas por cliente.",
            "agregar respostas de vários serviços em uma única resposta ao cliente.",
            "concentrar as regras de negócio dos serviços para evitar duplicação de código entre eles."],
      gab="E",
      com="**Gabarito: E.** Acumular lógica de negócio no gateway é um risco apontado na literatura: ele deve rotear, proteger e agregar, mas as regras ficam nos serviços (\"endpoints inteligentes, canais burros\").\n\n(A), (B), (C) e (D) são funções típicas do API Gateway: roteamento, autenticação/autorização centralizadas, rate limiting e composição de respostas."),

    Q(E, "06", 11, sub="11.3", pai="ESP-ARQ-0005", top="Microsserviços", k="arq-fowler-incorreta",
      enun="Segundo as características dos microsserviços descritas por James Lewis e Martin Fowler, é INCORRETO afirmar:",
      alts=["Os componentes são serviços executados em processos próprios, e não bibliotecas ligadas em memória.",
            "Os times são organizados em torno de capacidades de negócio, e não por camada técnica.",
            "A lógica fica nos serviços e a comunicação usa canais simples, como HTTP ou mensageria leve.",
            "A governança é centralizada, com uma única stack tecnológica obrigatória e um banco de dados corporativo compartilhado.",
            "Os serviços são projetados para falhas, exigindo monitoramento e recuperação rápida."],
      gab="D",
      com="**Gabarito: D.** Lewis e Fowler descrevem **governança descentralizada** (cada time escolhe ferramentas) e **gerenciamento de dados descentralizado** (banco por serviço, persistência poliglota).\n\n(A) Componentização via serviços. (B) Organização em torno de capacidades de negócio (Lei de Conway). (C) Smart endpoints and dumb pipes. (E) Design for failure. Todas estão corretas."),

    Q(E, "06", 11, sub="11.7", pai="ESP-ARQ-0006", top="Microsserviços", k="arq-cb-semiaberto",
      enun="Um circuit breaker protege as chamadas do serviço de Pix ao serviço de Antifraude. Depois de várias falhas seguidas, o circuito abriu; passado o tempo de espera configurado, o disjuntor deixa passar algumas chamadas de teste para verificar se o Antifraude se recuperou. Nesse momento, o circuit breaker está no estado",
      alts=["fechado.",
            "aberto.",
            "semiaberto (half-open).",
            "degradado (fallback).",
            "isolado (bulkhead)."],
      gab="C",
      com="**Gabarito: C.** No estado **semiaberto** (half-open) algumas chamadas de teste passam; se derem certo, o circuito fecha; se falharem, volta a abrir.\n\n(A) Fechado é o funcionamento normal, com todas as chamadas passando. (B) Aberto bloqueia as chamadas e falha imediatamente. (D) Fallback é a resposta alternativa usada quando a chamada falha, não um estado do disjuntor. (E) Bulkhead é outro padrão (isolamento de recursos)."),

    Q(E, "06", 11, sub="11.7", pai="ESP-ARQ-0006", top="Microsserviços", k="arq-bulkhead", mv="E",
      enun="No serviço de Internet Banking, as chamadas ao serviço de Câmbio, que anda lento, passaram a consumir todas as threads do pool HTTP, derrubando também as consultas de saldo. A solução foi reservar pools de threads e conexões separados para cada dependência, de modo que a lentidão de uma não esgote os recursos das outras. Trata-se do padrão",
      alts=["Retry com backoff exponencial.",
            "Circuit Breaker.",
            "Saga.",
            "Bulkhead (antepara).",
            "API Composition."],
      gab="D",
      com="**Gabarito: D.** O **Bulkhead** isola recursos (pools de threads/conexões) por dependência, como os compartimentos estanques de um navio.\n\n(A) Retry repete chamadas que falharam por motivo transitório; aqui pioraria o esgotamento. (B) O circuit breaker para de chamar o serviço após falhas, mas não reserva recursos separados. (C) Saga trata consistência de transações distribuídas. (E) API Composition junta resultados de vários serviços."),

    Q(E, "06", 11, sub="11.7", pai="ESP-ARQ-0007", top="Microsserviços", k="arq-cqrs",
      enun="O serviço de Extratos recebe milhares de consultas por segundo, enquanto as gravações de lançamentos são bem menos frequentes e exigem validações complexas. A equipe decidiu manter um modelo de escrita para os comandos e um modelo de leitura desnormalizado, em banco separado e otimizado para consultas, atualizado a partir dos eventos de escrita. Esse padrão é o",
      alts=["CQRS.",
            "Saga.",
            "Database per service.",
            "Strangler Fig.",
            "Service Discovery."],
      gab="A",
      com="**Gabarito: A.** O **CQRS** (Command Query Responsibility Segregation) separa o modelo de escrita (comandos) do de leitura (consultas), que podem ter bancos e estruturas diferentes.\n\n(B) Saga coordena transações locais com compensações. (C) Database per service define que cada serviço tem seu banco, mas não separa leitura de escrita dentro do serviço. (D) Strangler Fig migra legados aos poucos. (E) Service Discovery localiza instâncias de serviços."),

    Q(E, "06", 11, sub="11.7", pai="ESP-ARQ-0007", top="Microsserviços", k="arq-outbox", mv="E",
      enun="Ao registrar uma transferência, o serviço de Contas grava o lançamento no seu banco e publica o evento *TransferenciaRealizada* no broker. Em uma queda entre as duas operações, o lançamento foi gravado, mas o evento nunca foi publicado. Para garantir a consistência entre banco e mensageria, sem transação distribuída, o padrão indicado é",
      alts=["gravar o evento em uma tabela de saída na mesma transação local do lançamento e publicá-lo depois por um processo separado (outbox transacional).",
            "usar commit em duas fases entre o banco de dados e o broker de mensagens.",
            "aumentar o timeout da publicação no broker para evitar a perda do evento.",
            "substituir a mensageria por chamadas síncronas REST a todos os serviços interessados.",
            "aplicar um circuit breaker na chamada ao banco de dados."],
      gab="A",
      com="**Gabarito: A.** No **outbox transacional**, o evento é gravado numa tabela \"outbox\" na **mesma transação local** do dado; um processo separado o publica, garantindo que dado e evento fiquem consistentes.\n\n(B) O 2PC é bloqueante, pouco escalável e muitas vezes não suportado pelo broker; é o que se quer evitar. (C) Timeout maior não resolve a queda entre as duas operações. (D) Chamadas síncronas aumentam o acoplamento temporal e não resolvem a atomicidade. (E) Circuit breaker evita falhas em cascata; não garante atomicidade."),

    Q(E, "06", 18, sub="18.3", pai="ESP-ARQ-0008", top="Arquitetura e práticas complementares: hexagonal, legados, versionamento semântico, IA…", k="arq-acl",
      enun="Um banco está criando um novo serviço de Cadastro que precisa consultar o sistema legado de clientes em mainframe, cujo modelo usa códigos e estruturas de registro antigos. Para que esses conceitos não \"contaminem\" o modelo de domínio do novo serviço, cria-se um componente tradutor entre os dois modelos. No vocabulário do DDD, esse componente é a",
      alts=["camada anticorrupção (anti-corruption layer).",
            "figueira estranguladora (strangler fig).",
            "linguagem ubíqua (ubiquitous language).",
            "raiz de agregado (aggregate root).",
            "relação conformista (conformist)."],
      gab="A",
      com="**Gabarito: A.** A **camada anticorrupção** traduz entre o modelo do legado e o modelo novo, protegendo o domínio novo.\n\n(B) Strangler Fig substitui o legado aos poucos, roteando funções para o sistema novo; não é um tradutor de modelos. (C) Linguagem ubíqua é o vocabulário comum dentro de um contexto delimitado. (D) Raiz de agregado é a entidade que controla o acesso a um agregado. (E) Na relação conformista o consumidor **adota** o modelo do fornecedor, o oposto do que se quer."),

    Q(E, "06", 18, sub="18.1", pai="ESP-ARQ-0009", top="Arquitetura e práticas complementares: hexagonal, legados, versionamento semântico, IA…", k="arq-hex-driven",
      enun="Na arquitetura hexagonal (portas e adaptadores) de um serviço de empréstimos, considere os componentes: (1) controlador REST que recebe pedidos de simulação; (2) consumidor de uma fila de propostas; (3) repositório que grava contratos no PostgreSQL; (4) cliente HTTP que consulta o birô de crédito. São adaptadores secundários (de saída, *driven*), acionados pelo núcleo da aplicação, apenas",
      alts=["1 e 2.",
            "1 e 3.",
            "2 e 4.",
            "3 e 4.",
            "1, 2 e 4."],
      gab="D",
      com="**Gabarito: D.** Adaptadores **secundários (driven)** são aqueles que o núcleo chama: repositório de banco (3) e cliente de API externa (4).\n\n(1) O controlador REST e (2) o consumidor de fila **chamam** o núcleo: são adaptadores **primários (driving)**. Por isso as combinações que incluem 1 ou 2 estão erradas."),

    Q(E, "06", 18, sub="18.1", pai="ESP-ARQ-0009", top="Arquitetura e práticas complementares: hexagonal, legados, versionamento semântico, IA…", k="arq-hex-correta", mv="E",
      enun="Sobre a arquitetura hexagonal e as arquiteturas Onion e Clean Architecture, é correto afirmar:",
      alts=["o domínio depende diretamente das classes do framework web e do driver do banco de dados.",
            "as dependências apontam para o domínio, que define portas implementadas por adaptadores de cada tecnologia.",
            "a camada de persistência fica no centro, e as regras de negócio a envolvem.",
            "o teste do domínio exige subir banco de dados e servidor web reais, pois não há como substituir adaptadores.",
            "a hexagonal proíbe o uso de bancos relacionais, admitindo apenas mensageria."],
      gab="B",
      com="**Gabarito: B.** Em todas essas arquiteturas o **domínio fica no centro** e **as dependências apontam para dentro** (aplicação do princípio da inversão de dependência); o domínio define portas e os adaptadores as implementam.\n\n(A) O domínio não conhece framework nem banco. (C) Quem fica no centro é o domínio, não a persistência. (D) Um dos benefícios é testar o domínio com adaptadores falsos. (E) Não há restrição de tecnologia: o banco relacional entra por um adaptador."),

    Q(E, "06", 18, sub="18.3", pai="ESP-ARQ-0010", top="Arquitetura e práticas complementares: hexagonal, legados, versionamento semântico, IA…", k="arq-strangler-cenario",
      enun="Uma instituição decidiu modernizar seu sistema monolítico de cobrança. Um roteador passou a receber todas as requisições; a cada sprint, uma funcionalidade é reescrita como serviço novo e o roteador desvia o tráfego correspondente para ele, até que o monolito não atenda mais nada e possa ser desligado. A estratégia adotada é a",
      alts=["big bang, com substituição integral em uma única implantação.",
            "lift and shift, movendo o monolito para máquinas virtuais em nuvem.",
            "figueira estranguladora (Strangler Fig).",
            "camada anticorrupção, traduzindo os modelos do legado.",
            "implantação blue-green, alternando entre dois ambientes completos."],
      gab="C",
      com="**Gabarito: C.** O **Strangler Fig** substitui o legado **gradualmente**, desviando o tráfego para o código novo até o legado poder ser desligado.\n\n(A) Big bang é o oposto: troca tudo de uma vez. (B) Lift and shift (rehost) move a aplicação sem reescrevê-la. (D) A camada anticorrupção traduz modelos, mas não é a estratégia de substituição incremental. (E) Blue-green é estratégia de implantação de versões, não de migração de legado."),

    # ---------------- inéditas ----------------
    Q(E, "06", 9, sub="9.8", k="arq-3tier",
      enun="Em uma arquitetura multicamadas física de três níveis (*3-tier*) típica de aplicações web, os níveis correspondem, respectivamente, a",
      alts=["navegador do cliente, servidor de aplicação e servidor de banco de dados.",
            "controlador, modelo e visão, executados no mesmo processo.",
            "cliente gordo com regras de negócio, servidor de arquivos e SGBD.",
            "API Gateway, service mesh e sidecar.",
            "camada física, camada de enlace e camada de rede."],
      gab="A",
      com="**Gabarito: A.** No **3 tier** clássico da web: navegador (apresentação), servidor de aplicação (lógica) e servidor de banco (dados).\n\n(B) MVC é padrão lógico de interface, não divisão física em tiers. (C) Cliente gordo + SGBD caracteriza o 2 tier. (D) São componentes de infraestrutura de microsserviços. (E) São camadas do modelo OSI."),

    Q(E, "06", 9, sub="9.8", k="arq-n-tier-vantagem",
      enun="Ao migrar de uma arquitetura cliente-servidor de duas camadas (cliente gordo acessando o SGBD) para uma arquitetura de três camadas físicas, uma vantagem esperada é",
      alts=["eliminar a necessidade de rede entre cliente e servidor.",
            "dispensar o controle de concorrência no banco de dados.",
            "garantir que nenhuma regra de negócio precise ser testada.",
            "centralizar a lógica no servidor de aplicação, facilitando atualizações e permitindo escalar essa camada independentemente.",
            "obrigar que todas as camadas sejam escritas na mesma linguagem."],
      gab="D",
      com="**Gabarito: D.** Com a lógica no servidor de aplicação, uma mudança de regra não exige redistribuir o cliente, e a camada intermediária pode ser replicada/escalada sem mexer no banco.\n\n(A) A comunicação continua sendo pela rede. (B) Concorrência no banco continua necessária. (C) Testes continuam necessários. (E) As camadas podem usar tecnologias diferentes."),

    Q(E, "06", 9, sub="9.4", k="arq-objetos-distribuidos",
      enun="Em uma arquitetura de objetos distribuídos (como Java RMI ou CORBA), o cliente invoca métodos de um objeto remoto como se ele fosse local. O componente do lado cliente que implementa a mesma interface do objeto remoto, empacota (*marshalling*) os parâmetros e os envia pela rede é o",
      alts=["skeleton.",
            "stub, que atua como proxy remoto.",
            "registro de serviços UDDI.",
            "adaptador primário da arquitetura hexagonal.",
            "message broker."],
      gab="B",
      com="**Gabarito: B.** O **stub** é o **proxy remoto** do lado cliente: tem a mesma interface do objeto, faz o marshalling e envia a chamada. É uma aplicação do padrão Proxy (proxy remoto) citado na apostila.\n\n(A) O skeleton fica do lado **servidor**, desempacota a chamada e invoca o objeto real. (C) UDDI é registro de Web Services SOAP. (D) Adaptador primário é conceito da arquitetura hexagonal. (E) O broker intermedeia mensagens assíncronas, não representa um objeto remoto."),

    Q(E, "06", 10, sub="10.1", k="arq-soa-principios",
      enun="Entre os princípios de projeto de serviços em SOA propostos por Thomas Erl, aquele segundo o qual o serviço deve minimizar a retenção de informações entre uma requisição e outra é o princípio da",
      alts=["autonomia.",
            "abstração.",
            "composição.",
            "descoberta.",
            "ausência de estado (statelessness)."],
      gab="E",
      com="**Gabarito: E.** **Ausência de estado** (statelessness): o serviço minimiza a retenção de estado entre requisições, o que favorece escalabilidade e reúso.\n\n(A) Autonomia: o serviço controla seu ambiente e sua lógica. (B) Abstração: o contrato expõe só o essencial. (C) Composição: serviços podem ser combinados em serviços maiores. (D) Descoberta: metadados permitem encontrar o serviço."),

    Q(E, "06", 10, sub="10.1", k="arq-orquestracao-coreografia",
      enun="Considere dois desenhos de integração de serviços: no primeiro, um processo central escrito em WS-BPEL controla a ordem e a lógica das chamadas; no segundo, não há coordenador central, e cada serviço reage às mensagens que recebe e sabe com quem interagir. Esses desenhos correspondem, respectivamente, a",
      alts=["coreografia e orquestração.",
            "orquestração e coreografia.",
            "ESB e UDDI.",
            "saga coreografada e commit em duas fases.",
            "publicação e descoberta no registro de serviços."],
      gab="B",
      com="**Gabarito: B.** **Orquestração** = coordenador central (WS-BPEL); **coreografia** = controle distribuído, sem coordenador (WS-CDL).\n\n(A) Inverte os conceitos, pegadinha comum. (C) ESB é barramento de integração e UDDI é registro de serviços. (D) 2PC é protocolo de transação distribuída, não estilo de composição. (E) Publicar e descobrir são operações do triângulo SOA, não desenhos de composição."),

    Q(E, "06", 10, sub="10.1", k="arq-esb",
      enun="Em uma arquitetura SOA corporativa, o componente que faz roteamento de mensagens, transformação de formatos (por exemplo, com XSLT), conversão de protocolos e mediação entre sistemas heterogêneos é o",
      alts=["ESB (Enterprise Service Bus).",
            "service mesh.",
            "API Gateway do tipo BFF.",
            "balanceador de carga de camada 4.",
            "registro de serviços Eureka."],
      gab="A",
      com="**Gabarito: A.** O **ESB** é o barramento \"inteligente\" típico da SOA: roteamento, transformação, conversão de protocolos e mediação.\n\n(B) Service mesh cuida da comunicação serviço a serviço em microsserviços, sem transformar mensagens de negócio. (C) O BFF é um gateway por tipo de front-end. (D) Balanceador L4 distribui conexões TCP/UDP, sem entender o conteúdo. (E) Eureka é registro para descoberta de serviços."),

    Q(E, "06", 11, sub="11.9", k="arq-soa-x-micro",
      enun="Comparando a SOA tradicional com a arquitetura de microsserviços, é correto afirmar que",
      alts=["a SOA usa canais burros e endpoints inteligentes, enquanto os microsserviços dependem de um ESB inteligente.",
            "os microsserviços privilegiam um banco de dados compartilhado por todos os serviços, ao passo que a SOA exige banco por serviço.",
            "a SOA tem foco na integração no nível da empresa, com governança mais centralizada, e os microsserviços estruturam uma aplicação em serviços menores com governança descentralizada.",
            "microsserviços só podem se comunicar por SOAP e WS-*.",
            "a SOA proíbe o reúso de serviços entre processos de negócio."],
      gab="C",
      com="**Gabarito: C.** SOA: escopo corporativo, ESB, serviços maiores, governança centralizada. Microsserviços: arquitetura de uma aplicação, serviços menores, banco por serviço, governança descentralizada.\n\n(A) Está invertido: o ESB é da SOA; microsserviços usam canais burros. (B) Também invertido: em SOA é comum dado compartilhado; em microsserviços, banco por serviço. (D) Microsserviços usam REST/JSON, gRPC e eventos. (E) Reusabilidade é princípio da SOA."),

    Q(E, "06", 11, sub="11.5", k="arq-evento-comando",
      enun="Na mensageria entre microsserviços, a mensagem *ContaAberta*, publicada pelo serviço de Contas para que quaisquer serviços interessados (Cartões, Marketing, Antifraude) reajam, sem que o emissor os conheça, é um exemplo de",
      alts=["comando, enviado a um único destinatário para que execute uma ação.",
            "consulta síncrona do tipo requisição-resposta.",
            "chamada RPC com acoplamento temporal.",
            "transação de compensação de uma saga orquestrada.",
            "evento de domínio, distribuído no modelo publish/subscribe."],
      gab="E",
      com="**Gabarito: E.** Um **evento** notifica que algo **aconteceu** e pode ter vários interessados (publish/subscribe); o emissor não conhece os consumidores — base da arquitetura orientada a eventos.\n\n(A) Comando **pede** que algo seja feito e tem um destinatário. (B) e (C) São interações síncronas, com acoplamento temporal. (D) Compensação desfaz uma etapa da saga; *ContaAberta* apenas informa um fato."),

    Q(E, "06", 11, sub="11.5", k="arq-fila-vs-topico",
      enun="Um banco precisa distribuir as ordens de geração de boletos entre várias instâncias de um mesmo serviço, de modo que cada ordem seja processada por apenas uma instância; e, separadamente, avisar vários sistemas diferentes sempre que um boleto for pago. Os modelos de mensageria mais adequados são, respectivamente,",
      alts=["tópico publish/subscribe e fila ponto a ponto.",
            "fila ponto a ponto (consumidores concorrentes) e tópico publish/subscribe.",
            "chamada REST síncrona e fila ponto a ponto.",
            "tópico publish/subscribe nos dois casos, sem grupos de consumidores.",
            "commit em duas fases e chamada gRPC."],
      gab="B",
      com="**Gabarito: B.** Na **fila ponto a ponto**, cada mensagem é entregue a **um** consumidor (consumidores concorrentes dividem a carga). No **tópico publish/subscribe**, cada assinante recebe sua cópia do evento.\n\n(A) Inverte os modelos. (C) REST síncrono não distribui trabalho assíncrono nem absorve picos. (D) Um tópico sem grupos de consumidores entregaria a mesma ordem a todas as instâncias, duplicando boletos. (E) 2PC e gRPC não são modelos de mensageria."),

    Q(E, "06", 11, sub="11.5", k="arq-idempotente",
      enun="Brokers de mensagens costumam oferecer entrega *pelo menos uma vez* (at-least-once), o que pode gerar mensagens duplicadas. Para que o consumidor que credita valores em conta não credite duas vezes a mesma transferência, a medida adequada é",
      alts=["tornar o consumidor idempotente, registrando o identificador de cada mensagem já processada e ignorando repetições.",
            "aumentar o número de partições do tópico.",
            "desativar as confirmações (ack) do consumidor.",
            "trocar a fila por um tópico publish/subscribe.",
            "aplicar retry com backoff exponencial no produtor."],
      gab="A",
      com="**Gabarito: A.** Com entrega at-least-once, o consumidor deve ser **idempotente**: processar a mesma mensagem duas vezes deve ter o mesmo efeito de processá-la uma vez (por exemplo, guardando o ID da mensagem).\n\n(B) Mais partições aumentam o paralelismo, não evitam duplicatas. (C) Sem ack, o broker reenviaria ainda mais. (D) Tópicos não eliminam duplicidade. (E) Retry no produtor pode até **gerar** duplicatas."),

    Q(E, "06", 11, sub="11.5", k="arq-assincrono-vantagem",
      enun="Em comparação com a comunicação síncrona por REST entre microsserviços, a comunicação assíncrona por filas e tópicos tem como vantagem",
      alts=["a resposta imediata ao chamador, com a mesma latência de uma chamada local.",
            "a eliminação da consistência eventual.",
            "a depuração mais simples, pois o fluxo fica todo em uma única chamada.",
            "a garantia de que nenhuma mensagem será entregue em duplicidade.",
            "o menor acoplamento temporal, já que o consumidor processa a mensagem quando estiver disponível, absorvendo picos."],
      gab="E",
      com="**Gabarito: E.** A mensageria reduz o **acoplamento temporal**: emissor e consumidor não precisam estar no ar ao mesmo tempo, e a fila absorve picos.\n\n(A) Resposta imediata é característica da comunicação síncrona. (B) A comunicação assíncrona costuma **introduzir** consistência eventual. (C) A depuração fica mais difícil. (D) Duplicidade é um dos contras da mensageria."),

    Q(E, "06", 11, sub="11.4", k="arq-ddd-bounded",
      enun="No DDD (Domain-Driven Design), o termo \"Cliente\" tem significados diferentes nos contextos de Crédito (renda, score, limite) e de Marketing (preferências, campanhas). A fronteira dentro da qual um modelo e sua linguagem ubíqua são consistentes, e que costuma orientar a definição de um microsserviço, é o",
      alts=["agregado.",
            "objeto de valor.",
            "contexto delimitado (bounded context).",
            "repositório.",
            "serviço de domínio."],
      gab="C",
      com="**Gabarito: C.** O **contexto delimitado** é a fronteira de consistência de um modelo e de sua linguagem ubíqua; um bom microsserviço normalmente corresponde a um bounded context.\n\n(A) Agregado é um grupo de entidades tratado como unidade de consistência, dentro de um contexto. (B) Objeto de valor é definido pelos atributos, sem identidade própria. (D) Repositório abstrai a persistência de agregados. (E) Serviço de domínio abriga operações que não pertencem naturalmente a uma entidade."),

    Q(E, "06", 11, sub="11.4", k="arq-ddd-agregado",
      enun="Em um modelo DDD de contratos de empréstimo, a entidade Contrato controla suas Parcelas: nenhuma parcela é alterada diretamente de fora, apenas por meio de operações do Contrato, que garante as regras de consistência do conjunto. Nesse desenho, Contrato é",
      alts=["um objeto de valor.",
            "a raiz de um agregado.",
            "um contexto delimitado.",
            "uma camada anticorrupção.",
            "um evento de domínio."],
      gab="B",
      com="**Gabarito: B.** O **agregado** é um grupo de entidades tratado como unidade de consistência; o acesso de fora passa pela **raiz do agregado** (aqui, Contrato).\n\n(A) Objeto de valor não tem identidade e é imutável; Contrato tem identidade. (C) Contexto delimitado é uma fronteira de modelo, maior que uma entidade. (D) Camada anticorrupção traduz modelos entre sistemas. (E) Evento de domínio registra um fato ocorrido."),

    Q(E, "06", 11, sub="11.7", k="arq-discovery-cliente",
      enun="Em uma plataforma de microsserviços, as instâncias sobem e descem com IPs variáveis. O serviço de Pagamentos consulta o registro de serviços, obtém a lista de instâncias saudáveis do serviço de Tarifas e ele próprio escolhe, com balanceamento local, a instância que vai chamar. Essa abordagem é a",
      alts=["descoberta do lado do servidor (server-side discovery).",
            "configuração estática de IPs no código.",
            "resolução de nomes por arquivo hosts.",
            "descoberta do lado do cliente (client-side discovery).",
            "agregação de respostas pelo API Gateway."],
      gab="D",
      com="**Gabarito: D.** Na **descoberta no cliente**, o próprio cliente consulta o registro (Eureka, Consul) e escolhe a instância (balanceamento no cliente).\n\n(A) Na descoberta no servidor, o cliente chama um balanceador/roteador, que consulta o registro. (B) e (C) IP fixo ou arquivo hosts não acompanham instâncias dinâmicas. (E) Agregação de respostas é função do gateway, não descoberta."),

    Q(E, "06", 18, sub="18.2", k="arq-discovery-k8s",
      enun="No Kubernetes, o papel do registro de serviços em uma arquitetura de microsserviços é desempenhado nativamente por",
      alts=["ConfigMaps montados em cada pod.",
            "o objeto Service e o DNS interno do cluster, que dão nome e endereço estáveis a um conjunto de pods.",
            "volumes persistentes compartilhados entre os nós.",
            "o Horizontal Pod Autoscaler.",
            "o arquivo Dockerfile de cada imagem."],
      gab="B",
      com="**Gabarito: B.** No Kubernetes, o **Service** e o **DNS interno** fazem a descoberta: dão endereço estável e balanceamento para pods cujos IPs mudam.\n\n(A) ConfigMap guarda configuração. (C) Volumes guardam dados. (D) O HPA escala o número de pods. (E) O Dockerfile só constrói a imagem."),

    Q(E, "06", 11, sub="11.7", k="arq-retry-idempotencia",
      enun="Uma equipe configurou retries automáticos nas chamadas HTTP do aplicativo ao serviço de Pagamentos. Para que repetir uma requisição de pagamento após um timeout não gere cobranças em dobro, é necessário que",
      alts=["o retry seja feito imediatamente, sem intervalo, para reduzir a latência.",
            "o número de tentativas seja ilimitado.",
            "a operação seja idempotente, por exemplo com uma chave de idempotência enviada no cabeçalho da requisição.",
            "o timeout seja removido, esperando a resposta indefinidamente.",
            "as respostas de erro 4xx também sejam repetidas."],
      gab="C",
      com="**Gabarito: C.** Retry exige operação **idempotente**: com uma chave de idempotência, o servidor reconhece a repetição e devolve o resultado já processado.\n\n(A) Repetir sem intervalo agrava a sobrecarga; recomenda-se backoff exponencial com jitter. (B) Tentativas devem ser limitadas. (D) Nunca se espera indefinidamente: timeout é obrigatório. (E) Erros 4xx indicam problema na requisição e normalmente não devem ser repetidos."),

    Q(E, "06", 11, sub="11.7", k="arq-backoff-calc", tags=["calculo"], dif=3,
      enun="Um cliente HTTP chama o serviço de Cotações com timeout de 2 s por tentativa. Em caso de falha, faz até 4 novas tentativas (além da primeira), com backoff exponencial sem jitter: espera 100 ms antes da 1ª repetição e dobra a espera a cada nova repetição. Se o serviço não responder em nenhuma tentativa (todas esgotam o timeout), o tempo total até o cliente desistir é de",
      alts=["8,0 s.",
            "9,5 s.",
            "10,0 s.",
            "11,5 s.",
            "13,1 s."],
      gab="D",
      com="**Gabarito: D.** São 5 tentativas × 2 s = 10 s de timeouts, mais as esperas 100 + 200 + 400 + 800 = 1.500 ms. Total = 11,5 s.\n\n(A) 8,0 s considera só 4 tentativas e nenhuma espera. (B) 9,5 s = 4 tentativas (8 s) + 1,5 s de espera, esquecendo a tentativa inicial. (C) 10,0 s ignora as esperas do backoff. (E) 13,1 s soma uma 5ª espera de 1,6 s que não ocorre, pois não há repetição depois da última tentativa.\n\nConta conferida em `tools/verificacao/agente4/verif_arq.py`."),

    Q(E, "06", 11, sub="11.7", k="arq-cb-sim", tags=["calculo"], dif=3,
      enun="Um circuit breaker abre após **3 falhas consecutivas**, permanece aberto por **10 s** e, depois disso (isto é, a partir do instante em que completa 10 s aberto), deixa passar **1 chamada de teste** (semiaberto): se ela tiver sucesso, o circuito fecha; se falhar, reabre por mais 10 s. O cliente faz uma requisição a cada 2 s, de t = 0 s a t = 30 s (16 requisições). O serviço remoto falha em todas as chamadas recebidas entre t = 4 s e t = 19 s e responde normalmente fora desse intervalo. O número de requisições efetivamente encaminhadas ao serviço e, entre elas, o número de falhas são, respectivamente,",
      alts=["16 e 8.",
            "12 e 4.",
            "8 e 4.",
            "8 e 3.",
            "10 e 5."],
      gab="C",
      com="**Gabarito: C.** Simulação: t=0 e 2 sucesso; t=4, 6 e 8 falham → abre em t=8. t=10 a 16 bloqueadas. t=18 (10 s depois) é a chamada de teste e falha (o serviço ainda está fora) → reabre em t=18. t=20 a 26 bloqueadas. t=28 teste com sucesso → fecha; t=30 sucesso. Encaminhadas: 0, 2, 4, 6, 8, 18, 28, 30 = **8**; falhas: 4, 6, 8, 18 = **4**.\n\n(A) Seria o resultado sem circuit breaker (16 chamadas, 8 falhas de t=4 a t=18). (B) Considera que a chamada de teste em t=18 teria sucesso e que o circuito fecharia ali. (D) Esquece que a chamada de teste em t=18 também conta como falha. (E) Não corresponde a nenhuma sequência possível com as regras dadas.\n\nSimulação executada em `tools/verificacao/agente4/verif_arq.py`."),

    Q(E, "06", 11, sub="11.8", k="arq-disponibilidade-serie", tags=["calculo"],
      enun="Para concluir uma transferência, o aplicativo chama em sequência, de forma síncrona, três microsserviços cujas disponibilidades são 99,9%, 99,5% e 99,9%. Supondo falhas independentes e que a operação só tem sucesso se os três estiverem disponíveis, a disponibilidade da operação é de aproximadamente",
      alts=["99,90%.",
            "99,77%.",
            "99,50%.",
            "99,30%.",
            "98,30%."],
      gab="D",
      com="**Gabarito: D.** Em série, multiplicam-se as disponibilidades: 0,999 × 0,995 × 0,999 ≈ 0,99301 → **≈ 99,30%**. Cadeias síncronas longas reduzem a disponibilidade, um argumento a favor de comunicação assíncrona e de padrões de resiliência.\n\n(A) Pega o maior valor. (B) É a média aritmética (≈ 99,77%), que não se aplica. (C) Pega o menor valor; a cadeia é sempre **pior** que o elo mais fraco. (E) Erro de conta (subtrai 1,7 ponto).\n\nConta conferida em `tools/verificacao/agente4/verif_arq.py`."),

    Q(E, "06", 11, sub="11.2", k="arq-monolito-distribuido",
      enun="Uma empresa dividiu seu sistema em 20 serviços, mas todos compartilham o mesmo banco de dados e precisam ser implantados juntos a cada release, porque qualquer mudança de esquema quebra os demais. Segundo a literatura de microsserviços, essa situação caracteriza",
      alts=["um monolito modular, recomendado por Fowler no caminho \"monolith first\".",
            "uma arquitetura hexagonal com adaptadores secundários.",
            "uma saga coreografada.",
            "um service mesh mal configurado.",
            "um monolito distribuído, que soma as desvantagens das duas abordagens."],
      gab="E",
      com="**Gabarito: E.** Serviços tão acoplados que precisam ser implantados juntos formam um **monolito distribuído**: têm a complexidade de rede dos microsserviços sem a implantação independente.\n\n(A) O monolito modular é **uma** unidade de implantação bem modularizada, não 20 serviços acoplados. (B) Hexagonal trata do isolamento do domínio. (C) Saga é padrão de consistência de dados. (D) Service mesh cuida da comunicação; não causa acoplamento de esquema."),

    Q(E, "06", 11, sub="11.2", k="arq-conway",
      enun="\"Organizações projetam sistemas que copiam suas estruturas de comunicação.\" Essa afirmação, usada para justificar times multifuncionais organizados por capacidade de negócio em microsserviços, é conhecida como",
      alts=["Lei de Conway.",
            "Teorema CAP.",
            "Lei de Moore.",
            "Princípio de Pareto.",
            "Lei de Brooks."],
      gab="A",
      com="**Gabarito: A.** A **Lei de Conway** relaciona a estrutura do sistema à estrutura de comunicação da organização; por isso se organizam times por domínio (Pagamentos, Crédito).\n\n(B) CAP trata de consistência, disponibilidade e partição em sistemas distribuídos. (C) Moore fala da densidade de transistores. (D) Pareto é a regra 80/20. (E) Brooks: acrescentar pessoas a um projeto atrasado o atrasa ainda mais."),

    Q(E, "06", 11, sub="11.7", k="arq-cap",
      enun="Durante uma partição de rede entre duas regiões, um sistema distribuído de saldo de pontos de fidelidade continua aceitando leituras e escritas nas duas regiões e reconcilia os dados depois que a comunicação volta. À luz do teorema CAP, o sistema",
      alts=["privilegia consistência forte em detrimento da disponibilidade.",
            "privilegia disponibilidade, aceitando consistência eventual (modelo BASE).",
            "elimina a possibilidade de partição de rede.",
            "garante simultaneamente consistência forte, disponibilidade e tolerância a partição.",
            "usa transações ACID globais entre as regiões."],
      gab="B",
      com="**Gabarito: B.** Com partição (P), é preciso escolher entre C e A. Continuar atendendo nas duas regiões e reconciliar depois é escolher **disponibilidade** com **consistência eventual** (BASE).\n\n(A) Privilegiar consistência implicaria recusar operações durante a partição. (C) Partições não podem ser eliminadas por projeto. (D) O teorema diz justamente que não se garantem as três durante a partição. (E) ACID global exigiria coordenação, impossível durante a partição sem perder disponibilidade."),

    Q(E, "06", 11, sub="11.7", k="arq-event-sourcing",
      enun="Para atender exigências de auditoria, o serviço de Carteira de Investimentos deixou de gravar apenas a posição atual do cliente e passou a armazenar, em ordem, todos os fatos ocorridos (aplicação feita, resgate feito, rendimento creditado). A posição atual é obtida reproduzindo esses fatos. Trata-se de",
      alts=["CQRS.",
            "Event Sourcing.",
            "API Composition.",
            "Database per service.",
            "Outbox transacional."],
      gab="B",
      com="**Gabarito: B.** No **Event Sourcing** guarda-se a **sequência de eventos** que levou ao estado, reconstruído pela reprodução dos eventos; dá trilha de auditoria completa.\n\n(A) CQRS separa os modelos de leitura e escrita (é comum combiná-lo com Event Sourcing, mas são padrões distintos). (C) API Composition junta resultados de vários serviços. (D) Database per service define a propriedade dos dados. (E) Outbox garante a publicação de eventos junto com a transação local."),

    Q(E, "06", 11, sub="11.7", k="arq-mesh-x-gateway",
      enun="Sobre API Gateway e service mesh em uma plataforma de microsserviços, é correto afirmar:",
      alts=["o service mesh substitui o API Gateway na exposição de APIs a parceiros externos, com portal de desenvolvedores e cobrança por uso.",
            "o API Gateway exige alterar o código de cada serviço para implementar mTLS entre eles.",
            "ambos são bibliotecas que devem ser importadas no código-fonte dos serviços.",
            "o service mesh usa proxies sidecar para tratar a comunicação interna serviço a serviço (mTLS, retries, observabilidade), enquanto o API Gateway é a porta de entrada dos clientes externos.",
            "o service mesh é um tipo de ESB centralizado com transformação XSLT."],
      gab="D",
      com="**Gabarito: D.** O **service mesh** (Istio, Linkerd) usa **proxies sidecar** e cuida do tráfego interno (leste-oeste) sem alterar o código; o **API Gateway** é o ponto único de entrada dos clientes externos (norte-sul).\n\n(A) Exposição externa e gestão de APIs são funções do gateway. (B) mTLS automático entre serviços é justamente o que o mesh oferece sem mudar código. (C) Ambos são componentes de infraestrutura, não bibliotecas. (E) O mesh não é barramento com transformação de mensagens."),

    Q(E, "07", 2, sub="2.6", k="arq-cloud-native",
      enun="Segundo a CNCF, aplicações nativas de nuvem (cloud native) caracterizam-se pelo uso de",
      alts=["servidores físicos dedicados, configurados manualmente e atualizados no lugar.",
            "um único artefato monolítico implantado trimestralmente.",
            "contêineres, microsserviços, service meshes, infraestrutura imutável e APIs declarativas.",
            "sessões de usuário guardadas na memória local de cada instância.",
            "configuração fixa no código-fonte, igual em todos os ambientes."],
      gab="C",
      com="**Gabarito: C.** A definição da CNCF cita **contêineres, service meshes, microsserviços, infraestrutura imutável e APIs declarativas**.\n\n(A) Servidores atualizados no lugar caracterizam infraestrutura mutável (\"flocos de neve\"). (B) Releases raros e monolíticos se opõem à entrega contínua. (D) Estado na memória local impede escalar horizontalmente (12 fatores: processos sem estado). (E) O fator III manda guardar configuração em variáveis de ambiente."),

    Q(E, "07", 2, sub="2.6", k="arq-12fatores-processos",
      enun="Uma aplicação de internet banking guardava a sessão do usuário na memória do servidor de aplicação; ao escalar horizontalmente, os usuários eram desconectados quando o balanceador os mandava para outra instância. Pelo Twelve-Factor App, a correção alinhada ao fator \"Processos\" é",
      alts=["executar a aplicação como processos sem estado e guardar a sessão em um serviço de apoio, como um cache distribuído.",
            "gravar a sessão em arquivo local de cada instância.",
            "desativar o balanceador de carga.",
            "aumentar a memória de cada instância (escala vertical).",
            "fixar a configuração da sessão no código-fonte."],
      gab="A",
      com="**Gabarito: A.** O fator **VI (Processos)** pede processos **sem estado**; dados que precisam persistir ficam em **serviços de apoio** (banco, cache como Redis).\n\n(B) Arquivo local continua preso à instância. (C) Sem balanceador não há escala horizontal. (D) Escala vertical não resolve a troca de instância. (E) Configuração no código viola o fator III."),

    Q(E, "06", 9, sub="9.8", k="arq-pipes-filters", mv="E",
      enun="Um sistema de conciliação bancária recebe um arquivo de retorno e o faz passar por uma sequência de etapas independentes — validar layout, converter formato, enriquecer com dados do cliente, gravar —, em que a saída de cada etapa é a entrada da seguinte. Esse estilo arquitetural é o",
      alts=["repositório (dados compartilhados).",
            "cliente-servidor.",
            "duto e filtro (pipes and filters).",
            "orientado a eventos com publish/subscribe.",
            "MVC."],
      gab="C",
      com="**Gabarito: C.** Em **duto e filtro**, os dados fluem por uma sequência de transformações independentes (pipelines Unix, compiladores, ETL).\n\n(A) No repositório os componentes interagem por um armazenamento central. (B) Cliente-servidor separa quem oferece e quem consome serviços. (D) Em eventos, componentes reagem a eventos publicados, sem cadeia fixa. (E) MVC organiza interfaces interativas."),

    Q(E, "06", 11, sub="11.8", k="arq-contrato-pact",
      enun="Com dezenas de microsserviços evoluindo de forma independente, uma equipe passou a verificar, em cada pipeline, se o provedor de uma API ainda atende às expectativas registradas pelos seus consumidores, sem precisar subir o ambiente completo. Essa prática corresponde a",
      alts=["testes de carga com JMeter.",
            "testes de contrato orientados ao consumidor (por exemplo, com Pact).",
            "testes ponta a ponta em produção.",
            "análise estática de segurança (SAST).",
            "testes de mutação."],
      gab="B",
      com="**Gabarito: B.** **Testes de contrato** (Pact) verificam se provedor e consumidor continuam compatíveis, sem ambiente integrado completo — recomendados para microsserviços.\n\n(A) Teste de carga mede desempenho. (C) Ponta a ponta exige o sistema todo e é justamente o que se quer reduzir. (D) SAST procura vulnerabilidades no código. (E) Teste de mutação avalia a qualidade dos testes alterando o código."),

    Q(E, "06", 18, sub="18.3", k="arq-legado-fachada",
      enun="Um banco quer que novos canais digitais consultem saldos mantidos por programas COBOL em mainframe, sem reescrever o legado neste momento e sem que os canais conheçam os detalhes do mainframe. Entre os padrões de integração legado-moderno, a solução mais direta é",
      alts=["reescrever todo o core bancário em microsserviços antes de liberar os canais.",
            "dar aos canais acesso direto às tabelas do banco de dados do mainframe.",
            "exportar diariamente arquivos texto para cada canal.",
            "expor as funções do mainframe por APIs REST de fachada, publicadas no API Gateway.",
            "migrar o mainframe por rehost para máquinas virtuais em nuvem."],
      gab="D",
      com="**Gabarito: D.** **APIs de fachada** expõem funções do mainframe por REST, escondendo os detalhes do legado; publicadas no gateway, ganham autenticação e rate limiting.\n\n(A) Reescrever tudo antes é a abordagem big bang, de alto risco. (B) Acesso direto às tabelas cria acoplamento e ignora as regras do legado. (C) Arquivos diários não atendem consulta em tempo real. (E) Rehost muda a hospedagem, não oferece interface aos canais."),

    Q(E, "06", 11, sub="11.7", k="arq-observabilidade-tracing",
      enun="Uma requisição de abertura de conta passa por oito microsserviços e está lenta. Para identificar em qual serviço e em qual chamada o tempo está sendo gasto, a técnica mais adequada é",
      alts=["o rastreamento distribuído (distributed tracing), propagando um identificador de correlação entre os serviços.",
            "a análise do log local de apenas um dos serviços.",
            "o aumento do timeout de todas as chamadas.",
            "a substituição do API Gateway por um balanceador L4.",
            "a geração de um dump de memória do banco de dados."],
      gab="A",
      com="**Gabarito: A.** O **rastreamento distribuído** (OpenTelemetry, Jaeger, Zipkin) segue a requisição por todos os serviços, mostrando o tempo de cada trecho (spans), com ID de correlação propagado.\n\n(B) O log de um só serviço não mostra o caminho completo. (C) Aumentar timeout esconde o problema. (D) Trocar o gateway não dá visibilidade. (E) Dump do banco não mostra a cadeia de chamadas."),
]
